return ['domain'=>NULL,'plural-forms'=>'nplurals=2; plural=n != 1;','language'=>'bg_BG','project-id-version'=>'Ninja Forms','pot-creation-date'=>'2026-10-08T18:14:44+00:00','po-revision-date'=>'2026-10-08 00:00+0000','x-generator'=>'Ninja Forms bundled-translation builder','messages'=>['Ninja Forms'=>'Ninja Forms','https://ninjaforms.com/?utm_source=WordPress.org&utm_medium=Plugin+header'=>'https://ninjaforms.com/?utm_source=WordPress.org&utm_medium=Plugin+header','Free WordPress form builder with calculations, signatures, star ratings, unlimited submissions stored on your site, and an AI form builder.'=>'Безплатен инструмент за създаване на формуляри за WordPress с изчисления, подписи, оценки със звезди, неограничен брой отговори, съхранявани на вашия сайт, и създаване на формуляри с ИИ.','Saturday Drive'=>'Saturday Drive','http://ninjaforms.com/?utm_source=Ninja+Forms+Plugin&utm_medium=Plugins+WP+Dashboard'=>'http://ninjaforms.com/?utm_source=Ninja+Forms+Plugin&utm_medium=Plugins+WP+Dashboard','Ninja Form'=>'Ninja Form','Unique identifier for the object.'=>'Уникален идентификатор на обекта.','Maximum number of items to be returned in result set.'=>'Максимален брой елементи, които да бъдат върнати в резултата.','Current page of the collection.'=>'Текуща страница от колекцията.','Preview token failed validation'=>'Маркерът за преглед не премина проверката','Autoloader not found for Ninja Forms Blocks - try running %s'=>'Не е намерен autoloader за Ninja Forms Blocks, опитайте да изпълните %s','Ninja Forms Blocks was unable to load.'=>'Ninja Forms Blocks не успя да се зареди.','The form has reached its submission limit.'=>'Формулярът достигна ограничението си за отговори.','Update Submission'=>'Обновяване на отговор','Delete Submission'=>'Изтриване на отговор' . "\0" . 'Изтриване на отговори','Export Submissions'=>'Експортиране на отговори','Import Form'=>'Импортиране на формуляр','Forms'=>'Формуляри','The incomplete generated form could not be removed safely.'=>'Непъ